```java
public class Main {
    public static void main(String[] args) {
       int num;
       int a, b, c;
       System.out.print("세자리 정수 입력 : ");
       Scanner sc = new Scanner(System.in);
       num = sc.nextInt();
       a = num / 100;
       b = (num % 100) / 10;
       c = num % 10;

