```java
public static void main(String[] args) {
    int rand1, rand2;
    int cnt = 0;
    while(true) {
        cnt++;
        rand1 = (int) ((Math.random() * 6) + 1); // 랜덤 함수는 실수형으로 값이 생성되므로 형변환이 필요.
        rand2 = (int) ((Math.random() * 6) + 1);
