    }

    // 선택한 옵션을 포함한 제품 가격 구하기
    public String iPadProCalcPrice() {
        NumberFormat numberFormat = NumberFormat.getInstance();  // 숫자 형식 지정 객체 생성
        int[] screenPrice = {0, 1499000, 1999000};
